update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance industrielle à Valenciennes et dans le Nord","mecanisme":"Le Valenciennois fait cohabiter trois industries lourdes sur quelques kilomètres. L''automobile d''Onnaing à Douai, le pôle ferroviaire du matériel roulant, l''acier hérité de Denain et de Cambrai. Trois cadences, trois exigences de traçabilité. Nos techniciens itinérants couvrent le bassin, appuyés par le réseau national.","cta":"Demander une intervention à Valenciennes","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7 couvre les nuits, les week-ends et les jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 100","libelle":"collaborateurs, dont automaticiens SIEMENS et Schneider, roboticiens ABB et Fanuc"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"+ 120","libelle":"clients accompagnés, dont plus de 80 réguliers"}]},{"type":"probleme","punchline":"Une cellule robotisée se met en défaut à Onnaing. Toute la chaîne attend derrière, et la facture grimpe à chaque minute.","puces":[{"accroche":"Sur une chaîne automobile, l''arrêt se compte en minutes.","texte":"Presses, robots, convoyeurs : la cadence perdue ne se rattrape pas en fin de poste."},{"accroche":"Le ferroviaire exige la trace, pas seulement la réparation.","texte":"Une intervention non documentée devient un problème qualité."},{"accroche":"L''acier use les machines plus vite que le reste.","texte":"Laminoirs et machines tournantes réclament un préventif serré, jamais un dépannage au coup par coup."},{"accroche":"Le bon technicien est disputé sur tout le bassin.","texte":"Trois filières recrutent les mêmes profils en même temps, et vos annonces attendent."},{"accroche":"Un automate qui dit non bloque toute la ligne.","texte":"Sans quelqu''un capable de le lire, le diagnostic coûte deux jours de plus."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Automatisme et robotique","texte":"automaticiens SIEMENS et Schneider, roboticiens ABB et Fanuc, supervision et rétrofit."},"benefice":"Un défaut automate trouve quelqu''un capable de le lire, pas d''attendre le constructeur."},{"prestation":{"accroche":"Dépannage sur site","texte":"avec recherche de cause racine, du moteur à l''armoire électrique."},"benefice":"La ligne repart, et le compte rendu dit pourquoi elle s''était arrêtée."},{"prestation":{"accroche":"Préventif serré sur les équipements lourds","texte":"machines tournantes, transmissions, alignements, équilibrage."},"benefice":"Le parc acier tient la cadence au lieu de décrocher machine après machine."},{"prestation":{"accroche":"Interventions documentées","texte":"pour les filières à traçabilité, habilitations à jour."},"benefice":"Vos audits qualité trouvent une trace écrite pour chaque passage."},{"prestation":{"accroche":"Domaines combinés","texte":"[mécanique](/expertises/mecanique/), [électrique](/expertises/electrique/), [hydraulique](/expertises/hydraulique/), [soudure](/expertises/soudure/)."},"benefice":"Un seul interlocuteur pour un défaut qui mobilise plusieurs spécialités."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":", mobilisation de techniciens mobiles partout en France."},"benefice":"Une panne de nuit ne devient pas une équipe du matin à l''arrêt."},{"prestation":{"accroche":"Technicien en [Résidence](/offres/residence/)","texte":"intégré à votre équipe, prise de poste en 2 à 3 semaines."},"benefice":"Le poste que vous n''arrivez pas à pourvoir est tenu, remplacement assuré."},{"prestation":{"accroche":"Arrêt technique","texte":"cadré de J-90 à J-30, restitution à la demi-journée : voir l''offre [arrêt technique](/offres/arret-technique/)."},"benefice":"Votre arrêt programmé se rend à l''heure dite, pas au jugé."}],"prose":[{"texte":"Pour un montage de ligne, un transfert ou une extension, notre offre [chantier](/offres/chantier/) prend le relais avec un chef de projet unique."}]},{"type":"deroule","etapes":[{"titre":"Premier contact","texte":"vous décrivez la panne ou le projet. Un chargé d''affaires rappelle dans l''heure aux horaires ouvrés."},{"titre":"Qualification","texte":"machines, automates, accès au site, habilitations, contraintes de cadence. Tout se note avant le chiffrage."},{"titre":"Devis écrit","texte":"périmètre, créneaux, matériel, conditions horaires. Aucun surcoût découvert en fin de mission."},{"titre":"Intervention","texte":"accueil sécurité, plan de prévention, consignation, diagnostic, réparation, redémarrage sécurisé."},{"titre":"Compte rendu","texte":"opérations, temps passé, pièces, préconisations, versés dans votre GMAO."},{"titre":"Suivi","texte":"sur contrat, revue de la récurrence par équipement et du respect du plan préventif."}]},{"type":"garanties","puces":[{"accroche":"Le profil vous est présenté avant l''intervention.","texte":"Entretien technique et comportemental, 10 % des candidats retenus, résultats d''évaluation partagés, habilitations vérifiées."},{"accroche":"La cause racine est cherchée, pas seulement la panne réparée.","texte":"Chaque compte rendu dit ce qui a été trouvé et ce qui reste à traiter."},{"accroche":"Un périmètre et une sortie écrits.","texte":"Inclus, exclu, conditions d''astreinte, conditions d''arrêt du contrat."}]},{"type":"cta","question":"Besoin d''un automaticien sur votre ligne dans le Valenciennois ?","bouton":"Demander une intervention à Valenciennes","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"18 à 25 techniciens mobilisés sur plusieurs sites du Grand Est","texte":", pour accompagner la bascule vers le véhicule électrique depuis juin 2023","lienLibelle":"Étude de cas STELLANTIS : sites du Grand Est","lienHref":"/preuves/stellantis-grand-est/"},{"titre":"3 à 5 techniciens déployés sur la montée en cadence de plusieurs usines françaises","texte":", depuis septembre 2024","lienLibelle":"Étude de cas VALEO : plusieurs usines","lienHref":"/preuves/valeo-usines/"},{"titre":"Techniciens présents au quotidien sur les équipements critiques d''un fabricant de composants automobiles","texte":", depuis 2025","lienLibelle":"Étude de cas JTEKT : maintenance des installations","lienHref":"/preuves/jtekt/"},{"titre":"Maintenance préventive et curative d''une fonderie en service continu","texte":", depuis octobre 2023","lienLibelle":"Étude de cas STELLANTIS : fonderie de Sept-Fons","lienHref":"/preuves/stellantis-fonderie-sept-fons/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous vraiment à Valenciennes, alors que votre siège est à Lyon ?","reponse":"Oui. Nous n''avons pas de pignon sur rue dans le Valenciennois et nous le disons : nos techniciens se déplacent partout en France et interviennent sur site. Votre demande est rappelée dans l''heure aux horaires ouvrés, et le chargé d''affaires vous dit si le besoin est tenable."},{"question":"Quelles communes couvrez-vous ?","reponse":"Valenciennes, Anzin, Marly, Onnaing et Denain, avec leurs zones d''activité, jusqu''à Cambrai et Douai. Au-delà, nos techniciens se déplacent partout en France."},{"question":"Vos automaticiens travaillent-ils sur nos automates ?","reponse":"Oui, SIEMENS et Schneider, avec lecture des codes défaut, traitement des défauts intermittents, variation de vitesse et rétrofit. Les roboticiens interviennent sur ABB et Fanuc."},{"question":"Pouvez-vous renforcer notre équipe pendant une montée en cadence ?","reponse":"Oui. Technicien intégré à votre équipe en résidence, prise de poste en 2 à 3 semaines, remplacement assuré en cas d''absence. Le périmètre du poste s''écrit avec vous avant l''arrivée."},{"question":"Pouvez-vous reprendre un contrat de maintenance existant ?","reponse":"Oui. Reprise de l''historique, connexion à vos données d''arrêt, phase de recouvrement avec le prestataire sortant. La chaîne de responsabilité reste nette pendant la bascule."},{"question":"Que se passe-t-il en cas de panne la nuit ?","reponse":"L''astreinte 24/24 et 7/7 prend l''appel et mobilise un technicien. Le circuit d''appel et l''ordre des priorités sont écrits au devis, ligne par ligne."}]},{"type":"ctaFinal","question":"Besoin de fiabiliser votre parc avant le prochain lancement de série ?","bouton":"Demander une intervention à Valenciennes","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]}'::jsonb where path = '/implantations/maintenance-industrielle-valenciennes/';
